validator:
function validate(input) {
  const [{ Sales = [], Product = [] }] = input;
  const products = new Set(), sales = new Set();
  for (const [id, price] of Product) {
    if (id === null) return 'Every product needs a product_id.';
    if (products.has(id)) return `product_id ${id} appears twice in Product.`;
    products.add(id);
    if (price === null || price < 1) return `Product ${id} needs a price of at least 1.`;
  }
  for (const [id, productId, userId, quantity] of Sales) {
    if (id === null) return 'Every sale needs a sale_id.';
    if (sales.has(id)) return `sale_id ${id} appears twice in Sales.`;
    sales.add(id);
    if (!products.has(productId)) return `Sale ${id} names product_id ${productId}, which is not in Product.`;
    if (userId === null) return `Sale ${id} needs a user_id.`;
    if (quantity === null || quantity < 1) return `Sale ${id} needs a quantity of at least 1.`;
  }
  return null;
}

generator:
function generate(rand, size) {
  const pick = list => list[Math.floor(rand() * list.length)];
  const small = size === 'small';
  const productCount = small ? Math.floor(rand() * 4) : 300;
  const saleCount = productCount === 0 ? 0 : small ? Math.floor(rand() * 9) : 2000;
  const users = small ? [101, 102, 103] : Array.from({ length: 400 }, (_, i) => 1000 + i);
  // Small prices and quantities share factors, so different products often tie for a user's top spending.
  const prices = small ? [5, 10, 15, 20, 25, 30] : [1, 2, 3, 4, 5, 6, 8, 10, 12, 15, 20];
  const quantities = small ? [1, 2, 3, 4, 6] : [1, 2, 3, 4, 5, 6, 8, 10];
  const Product = [], Sales = [];
  for (let id = 1; id <= productCount; id++) Product.push([id, pick(prices)]);
  for (let id = 1; id <= saleCount; id++) Sales.push([id, 1 + Math.floor(rand() * productCount), pick(users), pick(quantities)]);
  return [{ Sales, Product }];
}
